 String digest(ByteBuffer b)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");d.update(b.duplicate());StringBuilder s=new StringBuilder();for(byte v:d.digest())s.append(String.format("%02x",v&255));return s.toString();}
 // Independent CPU barycentric material evaluation at a pixel center. Avoid
 // edge/texel boundaries, where OpenGL ownership/precision may differ.
 int[] expected(NativeSceneSnapshot scene,NativeSceneDrawPlan plan,float[][] sources,double x,double y){
  int[] color={0,0,0};
  for(int di=0;di<plan.count();di++){
   NativeSceneDrawPlan.Draw d=plan.draw(di);if(x<d.bounds.left||x>=d.bounds.right||y<d.bounds.top||y>=d.bounds.bottom)continue;float[] t=sources[di];ByteBuffer image=d.image();if(d.lighting!=null&&shadeColumns[di]!=null){int column=Math.max(0,Math.min(testViewportWidth-1,(int)Math.floor(x*testViewportWidth/240.0))),level=shadeColumns[di][column];image=d.lighting.variant(level);litEvaluations++;litLevelsMask|=1<<level;}
   for(int at=0;at<t.length;at+=15){double ax=t[at],ay=t[at+1],bx=t[at+5],by=t[at+6],cx=t[at+10],cy=t[at+11],den=(by-cy)*(ax-cx)+(cx-bx)*(ay-cy);if(den==0)continue;
    double a=((by-cy)*(x-cx)+(cx-bx)*(y-cy))/den,b=((cy-ay)*(x-cx)+(ax-cx)*(y-cy))/den,c=1-a-b;
    if(a<0||b<0||c<0){double da=a*Math.abs(den)/Math.hypot(bx-cx,by-cy),db=b*Math.abs(den)/Math.hypot(cx-ax,cy-ay),dc=c*Math.abs(den)/Math.hypot(ax-bx,ay-by);if(Math.min(da,Math.min(db,dc))>=-edgeRadius){exteriorEdgeSkips++;return null;}continue;}if(Math.min(a,Math.min(b,c))<.02)return null;
    double q=a*t[at+4]+b*t[at+9]+c*t[at+14],u=(a*t[at+2]+b*t[at+7]+c*t[at+12])/q,v=(a*t[at+3]+b*t[at+8]+c*t[at+13])/q;
    u=(u-Math.floor(u))*d.width;v=(v-Math.floor(v))*d.height;
    if(Math.min(u-Math.floor(u),Math.min(Math.ceil(u)-u,Math.min(v-Math.floor(v),Math.ceil(v)-v)))<.08)return null;
    int texel=((int)v*d.width+(int)u)*4;
    if((image.get(texel+3)&255)<(d.wall?192:128)){if(d.wall&&(image.get(texel+3)&255)<64){wallSkipEvaluations++;if(d.lighting!=null)litSkipChecks++;continue;}zeroChecks++;if(d.lighting!=null)litZeroChecks++;int row=Math.max(0,Math.min(159,(int)Math.floor(y)));ByteBuffer layer=scene.packedLayers();int ref=layer.getShort(20512+(row*25+24)*2)&65535,palette=layer.getShort(28512+ref*4096)&65535;for(int ch=0;ch<3;ch++){int value=(palette>>(ch*5))&31;color[ch]=(value<<3)|(value>>2);}}
    else if(d.indexed){int index=image.get(texel)&255;if(index==0)zeroChecks++;int row=Math.max(0,Math.min(159,(int)Math.floor(y)));ByteBuffer layer=scene.packedLayers();int ref=layer.getShort(20512+(row*25+24)*2)&65535,value=layer.getShort(28512+ref*4096+index*2)&65535;for(int ch=0;ch<3;ch++){int vch=(value>>(ch*5))&31;color[ch]=(vch<<3)|(vch>>2);}}else for(int ch=0;ch<3;ch++)color[ch]=image.get(texel+ch)&255; lastSample="command="+di+" model="+d.model+" index="+d.index+" wall="+d.wall+" uvTexel="+u+","+v+" texel="+texel+" rgb="+java.util.Arrays.toString(color);
   }
  }return color;
 }
 void afterReadback(NativeSceneSnapshot scene,int width,int height,int activeWidth,int activeHeight,ByteBuffer pixels){}
 String render(NativeSceneSnapshot scene,int width,int height,int activeWidth,int activeHeight,String image,boolean empty)throws Exception{
  int[] names=new int[1];GLES20.glGenTextures(1,names,0);int texture=names[0];GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,texture);GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D,GLES20.GL_TEXTURE_MIN_FILTER,GLES20.GL_NEAREST);GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D,GLES20.GL_TEXTURE_MAG_FILTER,GLES20.GL_NEAREST);GLES20.glTexImage2D(GLES20.GL_TEXTURE_2D,0,GLES20.GL_RGBA,width,height,0,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,null);GLES20.glGenFramebuffers(1,names,0);int fbo=names[0];GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,fbo);GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER,GLES20.GL_COLOR_ATTACHMENT0,GLES20.GL_TEXTURE_2D,texture,0);ok(GLES20.glCheckFramebufferStatus(GLES20.GL_FRAMEBUFFER)==GLES20.GL_FRAMEBUFFER_COMPLETE,"Framebuffer");
  NativeSceneDrawPlan plan=new NativeSceneDrawPlan(scene.geometry(0));int triangles;try(NativeSceneGpu gpu=new NativeSceneGpu()){triangles=gpu.draw(scene,activeWidth,activeHeight,width==240?(command)->{ByteBuffer trace=ByteBuffer.allocateDirect(4);GLES20.glReadPixels(136,27,1,1,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,trace);android.util.Log.e("NFSUGSceneGPU","PIXEL_AFTER "+command+" RGB "+(trace.get(0)&255)+","+(trace.get(1)&255)+","+(trace.get(2)&255));}:null);}ok(empty?triangles==0:triangles>0,"Triangle draw");ByteBuffer pixels=ByteBuffer.allocateDirect(width*height*4);GLES20.glReadPixels(0,0,width,height,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,pixels);ok(GLES20.glGetError()==GLES20.GL_NO_ERROR,"GPU readback");afterReadback(scene,width,height,activeWidth,activeHeight,pixels.asReadOnlyBuffer());
  if(empty){for(int i=0;i<width*height;i++)ok((pixels.get(i*4)|pixels.get(i*4+1)|pixels.get(i*4+2))==0,"Empty mesh did not clear");}else{testViewportWidth=activeWidth;shadeColumns=new int[plan.count()][];for(int di=0;di<plan.count();di++)if(plan.draw(di).lighting!=null&&plan.draw(di).lighting.curve!=null)shadeColumns[di]=plan.draw(di).lighting.curve.columns(activeWidth);float[][] source=new float[plan.count()][];for(int i=0;i<plan.count();i++){FloatBuffer v=plan.draw(i).mesh();source[i]=new float[v.remaining()];v.get(source[i]);}int[] precision={0};GLES20.glGetIntegerv(GLES20.GL_SUBPIXEL_BITS,precision,0);subpixelBits=precision[0];edgeRadius=Math.scalb(1.0,-subpixelBits)*Math.max(240.0/activeWidth,160.0/activeHeight);int tested=0,nonblack=0;for(int y=0;y<activeHeight;y+=Math.max(1,activeHeight/160))for(int x=0;x<activeWidth;x+=Math.max(1,activeWidth/240)){int[] color=expected(scene,plan,source,(x+.5)*240/activeWidth,(activeHeight-y-.5)*160/activeHeight);if(color==null)continue;int at=(y*width+x)*4;for(int c=0;c<3;c++)ok(Math.abs((pixels.get(at+c)&255)-color[c])<=1,"Texture/palette sample mismatch "+x+","+y+" expected="+java.util.Arrays.toString(color)+" actual="+(pixels.get(at)&255)+","+(pixels.get(at+1)&255)+","+(pixels.get(at+2)&255)+" "+lastSample);tested++;if((color[0]|color[1]|color[2])!=0)nonblack++;}ok(tested>=10&&nonblack>=5,"Insufficient source-derived pixel checks");checks+=tested;}
  pixels.position(0);String hash=digest(pixels);if(image!=null){int[] argb=new int[width*height];for(int y=0;y<height;y++)for(int x=0;x<width;x++){int at=((height-1-y)*width+x)*4;argb[y*width+x]=0xff000000|((pixels.get(at)&255)<<16)|((pixels.get(at+1)&255)<<8)|(pixels.get(at+2)&255);}Bitmap bitmap=Bitmap.createBitmap(argb,width,height,Bitmap.Config.ARGB_8888);try(FileOutputStream out=getTargetContext().openFileOutput(image,Context.MODE_PRIVATE)){ok(bitmap.compress(Bitmap.CompressFormat.PNG,100,out),"PNG");}bitmap.recycle();}
  GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,0);GLES20.glDeleteFramebuffers(1,new int[]{fbo},0);GLES20.glDeleteTextures(1,new int[]{texture},0);return hash;
 }
 // Explicit synthetic materials; geometry/order/ownership remain source-derived.
 NativeSceneSnapshot coverageScene(byte[] raw,boolean skipWalls){
  byte[] copy=raw.clone();ByteBuffer b=ByteBuffer.wrap(copy).order(ByteOrder.LITTLE_ENDIAN);int packet=(int)b.getLong(64);
  if(skipWalls){int world=packet+b.getInt(packet+48),identity=packet+b.getInt(packet+84),at=world+8,count=b.getInt(world+4);int changed=0;
   for(int i=0;i<count;i++){int corners=b.getInt(at),width=b.getInt(at+4),height=b.getInt(at+8),texture=at+12+corners*40;if(b.getInt(identity+8+i*20)==2){for(int pixel=0;pixel<width*height;pixel++){b.putInt(texture+pixel*4,0x000000ff);}changed++;}at=texture+width*height*4;}ok(changed>0,"No synthetic wall materials");
  }else{int section=packet+b.getInt(packet+36),model=section;if(b.getInt(section)==0x314c4d4e)model=section+b.getInt(section+8+2*8);int pixels=b.getInt(model+16)*b.getInt(model+20),texture=model+160+b.getInt(model+4)*24+b.getInt(model+8)+b.getInt(model+12)*18;
   for(int i=0;i<pixels;i++)copy[texture+i*4+3]=0;int layers=(int)b.getLong(96);for(int y=0;y<160;y++){int ref=b.getShort(layers+20512+(y*25+24)*2)&65535;b.putShort(layers+28512+ref*4096,(short)31);}
  }return new NativeSceneSnapshot(copy);
 }
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();boolean live=false;try{
  byte[] raw=Files.readAllBytes(new File(getTargetContext().getFilesDir(),"scene-gpu-whole.nab").toPath());NativeSceneSnapshot scene=new NativeSceneSnapshot(raw);startGl();live=true;int[] max=new int[1];GLES20.glGetIntegerv(GLES20.GL_MAX_TEXTURE_SIZE,max,0);ok(max[0]>=3840,"4K texture target unavailable");String small=render(scene,240,160,240,160,"scene-gpu-240.png",false),large=render(scene,3840,2160,3240,2160,"scene-gpu-4k.png",false);
  endGl();live=false;startGl();live=true;ok(render(scene,240,160,240,160,null,false).equals(small),"Context recreation changed model pixels");
  NativeSceneSnapshot skipScene=coverageScene(raw,true),zeroScene=coverageScene(raw,false);
  int beforeSkip=wallSkipEvaluations,beforeZero=zeroChecks;
  String skipHash=render(skipScene,240,160,240,160,null,false),zeroHash=render(zeroScene,240,160,240,160,null,false);
  render(skipScene,3840,2160,3240,2160,null,false);render(zeroScene,3840,2160,3240,2160,null,false);
  ok(wallSkipEvaluations>beforeSkip,"Ordered wall skip path not exercised");ok(zeroChecks>beforeZero,"Ordered palette-zero path not exercised");
  endGl();live=false;startGl();live=true;
  ok(render(skipScene,240,160,240,160,null,false).equals(skipHash),"Wall-skip context recreation changed pixels");
  ok(render(zeroScene,240,160,240,160,null,false).equals(zeroHash),"Palette-zero context recreation changed pixels");
  JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_SCENE_GLES_OFFSCREEN");report.put("source_commands",new NativeSceneDrawPlan(scene.geometry(0)).count());report.put("renderer",renderer);report.put("version",version);report.put("api",Build.VERSION.SDK_INT);report.put("subpixel_bits",subpixelBits);report.put("exterior_edge_skips",exteriorEdgeSkips);report.put("source_pixel_checks",checks);report.put("zero_texel_pixel_checks",zeroChecks);report.put("synthetic_zero_material",true);report.put("synthetic_wall_skip",true);report.put("wall_skip_evaluations",wallSkipEvaluations);report.put("wall_skip_native_sha256",skipHash);report.put("palette_zero_native_sha256",zeroHash);report.put("synthetic_context_recreated",true);report.put("native_rgba_sha256",small);report.put("four_k_frame_sha256",large);report.put("framebuffer","3840x2160");report.put("native_model_viewport","3240x2160");report.put("context_recreated",true);report.put("empty_mesh",false);report.put("full_scene",false);report.put("real_time_pacing",false);try(FileOutputStream out=getTargetContext().openFileOutput("scene-gpu-report.json",Context.MODE_PRIVATE)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable e){android.util.Log.e("NFSUGSceneGPU","Failed",e);result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{if(live)endGl();}}
